/**
 * useProducts Hook
 *
 * Custom hook for managing product CRUD operations and state.
 * Provides methods for fetching, creating, updating, and deleting products.
 *
 * Usage:
 *   const { products, isLoading, error, fetchProducts, createProduct, updateProduct, deleteProduct } = useProducts(organizationId)
 */

import { useState, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { Product, Category, CurrentPrice } from '@/types/database'

/**
 * Extended product type with current price and category info
 */
export interface ProductWithDetails extends Product {
  current_price?: CurrentPrice | null
  category?: Category | null
}

/**
 * Product form data interface
 */
export interface ProductFormData {
  name: string
  description?: string
  category_id?: string
  price?: number
  allergens?: string[]
  is_visible?: boolean
  image_url?: string
}

/**
 * Hook return type
 */
export interface UseProductsReturn {
  products: ProductWithDetails[]
  isLoading: boolean
  error: string | null
  fetchProducts: () => Promise<void>
  createProduct: (data: ProductFormData) => Promise<string>
  updateProduct: (id: string, data: ProductFormData) => Promise<void>
  deleteProduct: (id: string) => Promise<void>
  toggleVisibility: (id: string, isVisible: boolean) => Promise<void>
}

/**
 * Custom hook for product management
 *
 * @param organizationId - The organization ID to fetch products for
 * @returns Product state and CRUD methods
 */
export function useProducts(organizationId: string | undefined): UseProductsReturn {
  const [products, setProducts] = useState<ProductWithDetails[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  /**
   * Fetch products with their prices and categories
   */
  const fetchProducts = useCallback(async () => {
    if (!organizationId) return

    setIsLoading(true)
    setError(null)

    try {
      const supabase = createClient()

      // Fetch products
      const { data: productsData, error: productsError } = await supabase
        .from('products')
        .select('*')
        .eq('organization_id', organizationId)
        .order('created_at', { ascending: false })

      if (productsError) throw productsError

      // Fetch current prices
      const productIds = productsData?.map(p => p.id) || []
      let pricesMap: Record<string, CurrentPrice> = {}

      if (productIds.length > 0) {
        const { data: pricesData, error: pricesError } = await supabase
          .from('current_prices')
          .select('*')
          .in('product_id', productIds)

        if (pricesError) throw pricesError

        pricesMap = (pricesData || []).reduce((acc, price) => {
          acc[price.product_id] = price
          return acc
        }, {} as Record<string, CurrentPrice>)
      }

      // Fetch categories
      const { data: categoriesData, error: categoriesError } = await supabase
        .from('categories')
        .select('*')
        .eq('organization_id', organizationId)

      if (categoriesError) throw categoriesError

      const categoriesMap: Record<string, Category> = (categoriesData || []).reduce((acc, cat) => {
        acc[cat.id] = cat
        return acc
      }, {} as Record<string, Category>)

      // Combine products with prices and categories
      const productsWithDetails: ProductWithDetails[] = (productsData || []).map(product => ({
        ...product,
        current_price: pricesMap[product.id] || null,
        category: product.category_id ? categoriesMap[product.category_id] : null,
      }))

      setProducts(productsWithDetails)
    } catch (err) {
      setError('Failed to fetch products')
    } finally {
      setIsLoading(false)
    }
  }, [organizationId])

  /**
   * Create a new product
   */
  const createProduct = useCallback(async (data: ProductFormData): Promise<string> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const productData = {
      name: data.name.trim(),
      description: data.description?.trim() || null,
      category_id: data.category_id || null,
      allergens: data.allergens && data.allergens.length > 0 ? data.allergens : null,
      is_visible: data.is_visible ?? true,
      image_url: data.image_url?.trim() || null,
      organization_id: organizationId,
    }

    const { data: newProduct, error: insertError } = await supabase
      .from('products')
      .insert(productData)
      .select()
      .single()

    if (insertError) throw insertError

    // Add price if provided
    if (data.price !== undefined && data.price >= 0) {
      const { error: priceError } = await supabase
        .from('price_ledger')
        .insert({
          product_id: newProduct.id,
          price: data.price,
          currency: 'TRY',
          change_reason: 'Initial price',
        })

      if (priceError) throw priceError
    }

    return newProduct.id
  }, [organizationId])

  /**
   * Update an existing product
   */
  const updateProduct = useCallback(async (id: string, data: ProductFormData): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const productData = {
      name: data.name.trim(),
      description: data.description?.trim() || null,
      category_id: data.category_id || null,
      allergens: data.allergens && data.allergens.length > 0 ? data.allergens : null,
      is_visible: data.is_visible ?? true,
      image_url: data.image_url?.trim() || null,
    }

    const { error: updateError } = await supabase
      .from('products')
      .update(productData)
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError

    // Update price if provided and different from current
    if (data.price !== undefined && data.price >= 0) {
      const currentProduct = products.find(p => p.id === id)
      const currentPrice = currentProduct?.current_price?.price

      if (currentPrice !== data.price) {
        const { error: priceError } = await supabase
          .from('price_ledger')
          .insert({
            product_id: id,
            price: data.price,
            currency: 'TRY',
            change_reason: currentPrice !== undefined ? 'Price updated' : 'Initial price',
          })

        if (priceError) throw priceError
      }
    }
  }, [organizationId, products])

  /**
   * Delete a product
   */
  const deleteProduct = useCallback(async (id: string): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: deleteError } = await supabase
      .from('products')
      .delete()
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (deleteError) throw deleteError
  }, [organizationId])

  /**
   * Toggle product visibility
   */
  const toggleVisibility = useCallback(async (id: string, isVisible: boolean): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: updateError } = await supabase
      .from('products')
      .update({ is_visible: isVisible })
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError
  }, [organizationId])

  return {
    products,
    isLoading,
    error,
    fetchProducts,
    createProduct,
    updateProduct,
    deleteProduct,
    toggleVisibility,
  }
}
